def execute(arguments):
    """
    Base64编码/解码

    参数:
        arguments (dict): 包含以下字段
            - text (str): 要处理的文本，必填
            - operation (str): 操作类型，"encode"（编码）或 "decode"（解码），默认 "encode"
            - encoding (str): 字符编码，默认 "utf-8"

    返回:
        dict: 包含处理结果的字典
            - success (bool): 是否成功
            - result (str): 编码/解码后的结果
            - original (str): 原始文本
            - operation (str): 执行的操作
            - error (str): 错误信息（失败时）
    """
    import base64

    text = arguments.get("text", "")
    operation = arguments.get("operation", "encode")
    encoding = arguments.get("encoding", "utf-8")

    if not text:
        return {"success": False, "error": "请提供要处理的文本"}

    try:
        if operation == "encode":
            encoded = base64.b64encode(text.encode(encoding)).decode(encoding)
            return {
                "success": True,
                "result": encoded,
                "original": text,
                "operation": "encode"
            }
        elif operation == "decode":
            decoded = base64.b64decode(text.encode(encoding)).decode(encoding)
            return {
                "success": True,
                "result": decoded,
                "original": text,
                "operation": "decode"
            }
        else:
            return {"success": False, "error": f"未知的操作: {operation}"}
    except Exception as e:
        return {"success": False, "error": f"处理失败: {str(e)}"}
